function drawMagikarpGoldenKarp(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 3.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = Math.sin(breathPhase) * 4.0;

  const whiskerLag1 = Math.sin(t * 3.0) * 4.0;
  const whiskerLag2 = Math.cos(t * 3.0) * 3.0;

  // 1. Bóng nước
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Vây đuôi
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(16, by + 4); ctx.lineTo(34, by - 10); ctx.lineTo(30, by + 16); ctx.fill();
  ctx.strokeStyle = '#ea580c'; ctx.lineWidth = 1.5; ctx.stroke();

  // 3. Vây bụng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(-4, by + 18); ctx.lineTo(-12, by + 34); ctx.lineTo(8, by + 22); ctx.fill();

  // 4. Thân cam
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(0, by + 2, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 5. Vương miện 3 chóp
  ctx.fillStyle = '#facc15';
  ctx.beginPath();
  ctx.moveTo(-10, by - 12); ctx.lineTo(-16, by - 32); ctx.lineTo(-2, by - 14);
  ctx.lineTo(4,   by - 36); ctx.lineTo(10,  by - 12);
  ctx.lineTo(18,  by - 28); ctx.lineTo(16,  by - 8);
  ctx.fill();

  // 6. Vây ngực
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-4, by + 4); ctx.lineTo(14, by + 16); ctx.lineTo(16, by - 2); ctx.fill();
  ctx.strokeStyle = '#ea580c'; ctx.stroke();

  // 7. Môi hồng
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(-20, by + 4, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(-21, by + 4, 3, 0, Math.PI * 2); ctx.fill();

  // 8. Râu vàng
  ctx.strokeStyle = '#facc15'; ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-14, by + 8); ctx.lineTo(-22 + whiskerLag1, by + 22);
  ctx.lineTo(-18 + whiskerLag2, by + 36);
  ctx.stroke();

  // 9. Mắt ngơ ngác
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(-6, by - 2, 7, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.arc(-6, by - 2, 2, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.beginPath(); ctx.moveTo(-10, by - 2); ctx.lineTo(-2, by - 2); ctx.stroke();
  }

  ctx.restore();
}
